import{_ as o,r as t,o as l,c as p,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const g=JSON.parse('{"title":"Checkbox List Field - October CMS - 4.x","titleTemplate":false,"description":"Form Field","frontmatter":{"subtitle":"Form Field","shortname":"Checkbox List"},"headers":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}],"relativePath":"4.x/element/form/field-checkboxlist.md","filePath":"4.x/element/form/field-checkboxlist.md"}'),r={name:"4.x/element/form/field-checkboxlist.md"};function d(u,e,h,k,m,f){const a=t("pre-heading"),n=t("post-heading");return l(),p("div",null,[s(a),e[0]||(e[0]=c("h1",null,"Checkbox List Field",-1)),s(n),e[1]||(e[1]=i(`<p>The <code>checkboxlist</code> field renders a list of checkboxes. Checkbox lists support the same methods for defining the options as the <a href="./field-dropdown.html">dropdown field type</a> and also support secondary descriptions, found in the <a href="./field-radio.html">radio field type</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Permissions
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">open_account</span><span class="token punctuation">:</span> Open account
        <span class="token key atrule">close_account</span><span class="token punctuation">:</span> Close account
        <span class="token key atrule">modify_account</span><span class="token punctuation">:</span> Modify account
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>options</strong></td><td>available options for the list, as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>take options from a method defined on the model or as a static method, eg <code>Class::method</code>.</td></tr><tr><td><strong>default</strong></td><td>a default value to use for new records.</td></tr><tr><td><strong>quickselect</strong></td><td>show the quick selection buttons.</td></tr><tr><td><strong>cssClass</strong></td><td>used for setting the options as inline.</td></tr><tr><td><strong>inlineOptions</strong></td><td>display the options side-by-side instead of stacked, when less than 10 options.</td></tr><tr><td><strong>placeholder</strong></td><td>a message to display when there are no records selected (preview context).</td></tr><tr><td><strong>cumulative</strong></td><td>when checkboxes are nested, checking a parent will check all the children. Default: <code>false</code></td></tr></tbody></table></div><p>You may use the <code>default</code> property to set a default value, where the value is the key of the option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Permissions
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">default</span><span class="token punctuation">:</span> open_account
</code></pre></div><p>Options can be displayed inline with each other instead of in separate rows by setting the <code>inlineOptions</code> property to a <code>true</code> value. This only applies when there are less than 10 available options.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">inlineOptions</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>A quick select menu with &quot;Select All&quot; and &quot;Select None&quot; buttons will become visible when the list has greater than 10 items. To explicitly enable these buttons, use the <code>quickselect</code> option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">quickselect</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>When using <a href="./../define-options.html">detailed options</a> the checkboxes can appear in a nested structure, set the <code>cumulative</code> property to <code>true</code> if you want to check all child checkboxes when a parent checkbox is selected.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkboxlist
    <span class="token key atrule">cumulative</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../define-options.html">Detailed Option Definitions</a></li><li><a href="./field-dropdown.html">Dropdown Form Field</a></li><li><a href="./field-radio.html">Radio Form Field</a></li></ul></div>`,14))])}const b=o(r,[["render",d]]);export{g as __pageData,b as default};
